class ApiResponse<T> {
  final List<T> data;
  final int total;
  final int page;
  final int pageSize;
  final String? error;

  ApiResponse({
    required this.data,
    required this.total,
    required this.page,
    this.pageSize = 10,
    this.error,
  });

  bool get isSuccess => error == null;

  bool get hasMore => page * pageSize < total;

  int get totalPages => (total / pageSize).ceil();

  ApiResponse<T> nextPage() {
    return ApiResponse(
      data: data,
      total: total,
      page: page + 1,
      pageSize: pageSize,
      error: error,
    );
  }

  ApiResponse<T> filter(bool Function(T) predicate) {
    return ApiResponse(
      data: data.where(predicate).toList(),
      total: total,
      page: page,
      pageSize: pageSize,
      error: error,
    );
  }

  String describe() {
    return 'ApiResponse(page=$page/$totalPages, items=${data.length}/$total, success=$isSuccess)';
  }
}

void main() {
  final res = ApiResponse(data: [1, 2, 3], total: 10, page: 1);
  print(res.describe());
  print('Has more: ${res.hasMore}');
  print('Total pages: ${res.totalPages}');

  final next = res.nextPage();
  print('Next page: ${next.describe()}');

  final filtered = res.filter((x) => x > 1);
  print('Filtered: ${filtered.data}');

  final errorRes = ApiResponse<int>(data: [], total: 0, page: 1, error: 'Not found');
  print('Error: ${errorRes.describe()}');
}

