class RetryClient {
  final int maxRetries;
  final int baseDelayMs;
  final double backoffMultiplier;
  int _attempts = 0;

  RetryClient({
    this.maxRetries = 3,
    this.baseDelayMs = 100,
    this.backoffMultiplier = 2.0,
  });

  String fetchSync(String url) {
    _attempts++;
    if (url.contains('fail')) {
      if (_attempts <= maxRetries) {
        throw Exception('Network error');
      }
      return 'fallback response';
    }
    return 'Response from $url';
  }

  List<int> getRetryDelays() {
    final delays = <int>[];
    var delay = baseDelayMs;
    for (int i = 0; i < maxRetries; i++) {
      delays.add(delay);
      delay = (delay * backoffMultiplier).toInt();
    }
    return delays;
  }

  int get totalAttempts => _attempts;

  String describe() {
    return 'RetryClient(retries=$maxRetries, base=${baseDelayMs}ms, backoff=${backoffMultiplier}x)';
  }
}

void main() {
  final client = RetryClient(maxRetries: 3, baseDelayMs: 100);

  print(client.describe());
  print('Delays: ${client.getRetryDelays()}');

  final result = client.fetchSync('https://api.example.com/ok');
  print('Result: $result');
  print('Attempts: ${client.totalAttempts}');

  final failResult = client.fetchSync('https://api.example.com/fail');
  print('Fail result: $failResult');
  print('Attempts after fail: ${client.totalAttempts}');
}

