class RateLimiter {
  final int maxRequests;
  final int windowMs;
  final List<int> _timestamps = [];

  RateLimiter(this.maxRequests, this.windowMs);

  bool tryAcquire() {
    _cleanup();
    if (_timestamps.length >= maxRequests) return false;
    _timestamps.add(DateTime.now().millisecondsSinceEpoch);
    return true;
  }

  void reset() {
    _timestamps.clear();
  }

  int get remaining {
    _cleanup();
    return maxRequests - _timestamps.length;
  }

  double get usagePercent {
    _cleanup();
    return _timestamps.length / maxRequests;
  }

  int get totalAcquired => _timestamps.length;

  List<int> get timestamps => List.from(_timestamps);

  String describe() {
    _cleanup();
    return 'RateLimiter(${_timestamps.length}/$maxRequests per ${windowMs}ms)';
  }

  void _cleanup() {
    final now = DateTime.now().millisecondsSinceEpoch;
    _timestamps.removeWhere((ts) => now - ts > windowMs);
  }
}

void main() {
  final limiter = RateLimiter(3, 1000);
  print(limiter.describe());

  for (int i = 0; i < 5; i++) {
    final acquired = limiter.tryAcquire();
    print('Request ${i + 1}: $acquired (${limiter.remaining} remaining)');
  }
  print('Usage: ${(limiter.usagePercent * 100).toInt()}%');
}

