class UrlBuilder {
  final String baseUrl;
  final List<String> _paths = [];
  final Map<String, String> _queries = {};

  UrlBuilder(this.baseUrl);

  UrlBuilder path(String segment) {
    _paths.add(segment);
    return this;
  }

  UrlBuilder query(String key, String value) {
    _queries[key] = value;
    return this;
  }

  UrlBuilder queries(Map<String, String> params) {
    _queries.addAll(params);
    return this;
  }

  String build() {
    var url = baseUrl.replaceAll(RegExp(r'/+\$'), '');
    if (_paths.isNotEmpty) {
      url += '/${_paths.join('/')}';
    }
    if (_queries.isNotEmpty) {
      final qs = _queries.entries.map((e) => '${e.key}=${e.value}').join('&');
      url += '?$qs';
    }
    return url;
  }

  void reset() {
    _paths.clear();
    _queries.clear();
  }

  String get currentPath => _paths.join('/');

  String describe() => 'UrlBuilder($baseUrl, paths=${_paths.length}, queries=${_queries.length})';
}

void main() {
  final url = UrlBuilder('https://api.example.com');
  final built = url
      .path('users')
      .path('123')
      .query('token', 'abc')
      .query('format', 'json')
      .build();
  print(built);
  print(url.describe());
}
